"""Verify every generated byte, retained source, white corner and motion anchor."""
from copy import deepcopy
from PIL import Image, ImageChops
from pack import ROOT,FOLDER,EXPORTS,BASE,COVERBASE,REV,read,write,sha,sources,dimensions,BACKGROUND_CORNERS

baseline=read(FOLDER/'preservation-before.json')
assert sources()==baseline,'An existing source/catalog/immutable asset changed'
new_covers=read(ROOT/f'{COVERBASE}/animation-covers.json')
anchors=read(ROOT/f'{BASE}/anchors.json')
old_anchors=read(ROOT/'assets/exploded/brake-dr-20261005/anchors.json')
reports={};frames_total=0;chunks_total=0;max_anchor_delta=0;changed_masks=[]
for quality,oldname,newname,width,height in [
    ('sd','manifest.json','manifest-white-20261011.json',640,427),
    ('hd','manifest-detail.json','manifest-detail-white-20261011.json',1280,854)]:
    old=read(ROOT/'assets/exploded'/oldname);new=read(ROOT/'assets/exploded'/newname)
    assert new['revision']==REV and list(new['projects'])==list(old['projects'])
    bytes_total=0;chunk_count=0
    for key,p in new['projects'].items():
        previous=old['projects'][key]
        changed={'frames','poster','bytes','chunks','chunkBytes','chunkVersion','provenance'}
        assert {k:v for k,v in previous.items() if k not in changed}=={k:v for k,v in p.items() if k not in changed},key
        assert len(p['frames'])==len(previous['frames'])
        frames=[]
        for url in p['frames']:
            path,version=url.split('?v=');assert path.startswith(f'{BASE}/{quality}/')
            data=(ROOT/path).read_bytes();assert sha(data).startswith(version)
            dimensions(ROOT/path,width,height);frames.append(data)
        assert p['poster']==p['frames'][0]
        assert sum(map(len,frames))==p['bytes']==p['chunkBytes']
        seen=[]
        for i,chunk in enumerate(p['chunks']):
            path,version=chunk['url'].split('?v=');data=(ROOT/path).read_bytes()
            assert sha(data).startswith(version) and len(data)==chunk['bytes']<=256*1024
            assert 1<=len(chunk['frames'])<=(4 if i==0 else 16)
            offset=0
            for r in chunk['frames']:
                assert r['offset']==offset
                assert data[r['offset']:r['offset']+r['length']]==frames[r['index']]
                seen.append(r['index']);offset+=r['length']
            assert offset==len(data)
        assert seen==list(range(len(frames)))
        for n in [0,(len(frames)-1)//2,len(frames)-1]:
            with Image.open(ROOT/p['frames'][n].split('?')[0]) as image:
                assert ImageChops.difference(image.convert('RGB'),Image.new('RGB',image.size,'white')).getbbox(),(key,n,'blank image')
        prov=read(ROOT/p['provenance'])
        assert prov['background']=='#ffffff' and prov['coverProgress']==0
        for field,value in prov['camera'].items():
            before=prov['coverCamera'][field]
            # OrbitControls may accumulate sub-picometer roundoff while idle.
            pairs=zip(value,before) if isinstance(value,list) else [(value,before)]
            assert all(abs(a-b)<1e-10 for a,b in pairs),(key,field,'camera changed after cover')
        if quality=='sd':
            cover=new_covers['projects'][key]
            assert cover['coverProgress']==0 and cover['sourceFrame']==p['frames'][0]
            assert cover['sourceFrameSha256']==sha(frames[0])
            for v in cover['variants']:
                path=ROOT/v['src'];data=path.read_bytes();dimensions(path,v['width'],v['height'])
                assert sha(data)==v['sha256'] and len(data)==v['bytes']
                assert v['src']+'?v='+v['sha256'][:12] in cover['srcset']
            a=anchors[key];assert len(a['points'])==len(frames)
            assert all(point and 0<=point['x']<=1 and 0<=point['y']<=1 for point in a['points'])
            assert all(len(mask)==24 and any(mask) and all(0<=row<=4294967295 for row in mask) for mask in a['masks'])
            for before,after in zip(old_anchors[key]['points'],a['points']):
                max_anchor_delta=max(max_anchor_delta,abs(before['x']-after['x']),abs(before['y']-after['y']))
            if a['masks']!=old_anchors[key]['masks']:changed_masks.append(key)
        bytes_total+=p['bytes'];chunk_count+=len(p['chunks']);frames_total+=len(frames)
    reports[quality]={'frames':sum(len(p['frames']) for p in new['projects'].values()),'bytes':bytes_total,'chunks':chunk_count}
    chunks_total+=chunk_count

assert max_anchor_delta<=.000002,('Anchor projections changed',max_anchor_delta)
assert not changed_masks,('Occupancy masks changed',changed_masks)
assert anchors['ansysCfd']['legend']==old_anchors['ansysCfd']['legend']
result=read(EXPORTS/'result.json')
assert not result['errors'] and len(result['results'])==16
for key,p in result['results'].items():
    assert p['coverState']['progress']==0 and p['state']['progress']==1
    assert all(s['compiled'] for s in p['state']['sourceShaders']),(key,'source shader did not compile')
reports.update(status='passed',frames=frames_total,chunks=chunks_total,coverVariants=48,annotationSamples=sum(len(a['points']) for a in anchors.values()),phaseMasks=sum(len(a['masks']) for a in anchors.values()),maxAnchorDelta=max_anchor_delta,changedMasks=changed_masks,preservedFileCount=len(baseline),renderMilliseconds=result['elapsedMilliseconds'],nativeBackground='#ffffff',encodedBackgroundTolerance=3,encodedCornerCounts=dict(BACKGROUND_CORNERS))
write(FOLDER/'asset-verification.json',reports)
print(__import__('json').dumps(reports))
